{"path": "units/slugify/slugify.py", "content": "import re


class Impl:
    _NON_ALNUM = re.compile(r"[\W_]+", re.UNICODE)

    def slugify(self, text):
        slug = self._NON_ALNUM.sub("-", text.lower()).strip("-")
        return slug if slug else "untitled"
"}

{"path": "units/ranges/ranges.py", "content": "class Impl:
    def merge(self, ranges):
        if not ranges:
            return []
        intervals = sorted((min(a, b), max(a, b)) for a, b in ranges)
        merged = [list(intervals[0])]
        for start, end in intervals[1:]:
            if start <= merged[-1][1] + 1:  # overlapping or adjacent
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return [tuple(item) for item in merged]
"}
